-- ============================================================================
-- Migration: 0020_admin_reports.sql
-- Purpose:   P13-3 / TOM-68 asynchronous & scheduled admin reports
--            (Box Reports equivalent).
--
-- Design notes:
-- - Reports are generated by the existing `JOBS_QUEUE` consumer, not during
--   the HTTP request. The job row is the durable source of truth; the R2 CSV
--   object key is only written after the generation succeeded.
-- - `filters_json` keeps the normalized report filter contract (`from`, `to`,
--   `actorEmail`, `targetId`, `status`, `actionPrefix`, ...). JSON keeps the
--   schema additive without a migration for every future report filter.
-- - `expires_at` drives the daily Cron R2 purge. There is intentionally no
--   foreign key on `schedule_id` so deleting a schedule never deletes the
--   generated report history it produced.
-- - Schedules store their own `retention_days` so a tenant can keep weekly or
--   monthly exports for a different period than one-off requests.
-- ============================================================================

CREATE TABLE IF NOT EXISTS admin_report_jobs (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  schedule_id TEXT,
  report_type TEXT NOT NULL CHECK (report_type IN (
    'user_activity',
    'shared_links_inventory',
    'access_stats',
    'users_and_guests'
  )),
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN (
    'queued',
    'running',
    'completed',
    'failed'
  )),
  filters_json TEXT NOT NULL DEFAULT '{}',
  r2_object_key TEXT,
  row_count INTEGER NOT NULL DEFAULT 0,
  byte_size INTEGER NOT NULL DEFAULT 0,
  error_message TEXT,
  created_by TEXT NOT NULL,
  created_by_email TEXT,
  expires_at TEXT NOT NULL,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_admin_report_jobs_tenant_created
  ON admin_report_jobs(tenant_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS idx_admin_report_jobs_expires
  ON admin_report_jobs(expires_at);

CREATE TABLE IF NOT EXISTS admin_report_schedules (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  name TEXT NOT NULL,
  report_type TEXT NOT NULL CHECK (report_type IN (
    'user_activity',
    'shared_links_inventory',
    'access_stats',
    'users_and_guests'
  )),
  cadence TEXT NOT NULL CHECK (cadence IN ('weekly', 'monthly')),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  filters_json TEXT NOT NULL DEFAULT '{}',
  retention_days INTEGER NOT NULL DEFAULT 30,
  next_run_at TEXT NOT NULL,
  last_run_at TEXT,
  last_job_id TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_admin_report_schedules_due
  ON admin_report_schedules(enabled, next_run_at);
